mapper.select:
SELECT DISTINCT e.code FROM sa_drill_evidence e WHERE e.unlock_rule_code IS NULL AND e.scenario_id=(SELECT scenario_id FROM sa_drill_run WHERE id=#{runId})
UNION SELECT DISTINCT e.code FROM sa_drill_evidence e JOIN sa_drill_run_action a ON a.run_id=#{runId}
JOIN sa_drill_rule r ON r.id=a.matched_rule_id WHERE e.scenario_id=(SELECT scenario_id FROM sa_drill_run WHERE id=#{runId}) AND e.unlock_rule_code=r.code
